pre_audit_artifact.source:
function movePlayer(x,direction,seconds,width,speed){
  let newX = x + direction * speed * seconds;
  return Math.max(20, Math.min(width - 20, newX));
}
function overlaps(a,b){return a.x<b.x+b.w&&a.x+a.w>b.x&&a.y<b.y+b.h&&a.y+a.h>b.y}
function advanceWave(wave,remaining,spawned){return remaining===0&&spawned?wave+1:wave}
function tickCooldown(remaining,seconds){if(seconds<0){throw new Error("Invalid argument: seconds must be non-negative.")}return Math.max(0,remaining-seconds)}

